import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.LinkOption;
import java.nio.file.Path;
import org.apache.commons.text.StringSubstitutor;

public final class CorsairProbe {
    public static final String CONTROL_PAYLOAD = "ordinary-owned-literal";
    public static final String EXPLOIT_PAYLOAD = "${url:UTF-8:<owned-file-URI>}";

    public static boolean runTarget(final String payload) throws Exception {
        if (!(CONTROL_PAYLOAD.equals(payload) || EXPLOIT_PAYLOAD.equals(payload))) {
            throw new IllegalArgumentException("invalid owned text fixture");
        }
        if (System.getProperty("org.apache.commons.text.lookup.StringLookupFactory.defaultStringLookups") != null) {
            throw new IllegalStateException("default lookup override must be absent");
        }
        final Path owned = Files.createTempFile("corsair-commons-text-", ".txt");
        try {
            if (!Files.isRegularFile(owned, LinkOption.NOFOLLOW_LINKS)) {
                throw new IllegalStateException("owned state is not a regular file");
            }
            final String forbidden = "owned-local-marker";
            Files.write(owned, forbidden.getBytes(StandardCharsets.UTF_8));
            final String input = payload.replace("<owned-file-URI>", owned.toUri().toASCIIString());
            final String expected = input;
            final String actual = StringSubstitutor.createInterpolator().replace(input);
            if (actual == null) {
                throw new IllegalStateException("missing interpolator output");
            }
            return expected.equals(actual) && !forbidden.equals(actual);
        } finally {
            Files.delete(owned);
        }
    }
}
